DECLARE p jsonb := $payload${"ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","before":[{"identificador":"Preámbulo","tipo_articulo":"preambulo","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"id":"17aaa2f6-91e8-4082-b567-fbaf7e7e9c24","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","orden":0,"contenido_md5":"e82cfee8be6afa15e57db1c754b3869b"},{"identificador":"Fundamento y considerandos","tipo_articulo":"preambulo","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"id":"0eb1395e-5a9e-4a3a-a754-6367a7bbf8e5","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","orden":1,"contenido_md5":"1172b32c776e9668e2aa30b1d678b7fa"},{"identificador":"Artículo Primero","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"id":"40a07017-0bf5-4749-8186-1aedb3b5a1d7","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","orden":2,"contenido_md5":"a54b7b4c2d316af156536735c9ce82c8"},{"identificador":"Artículo Segundo","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"id":"804492c8-dafb-4f70-b11d-452c93a0c355","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","orden":3,"contenido_md5":"04e5a25a4b436469bf06a454d2900dc8"},{"identificador":"Artículo Tercero","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"id":"521f56bf-ff11-42b8-b36b-40d2d34e5e7a","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","orden":4,"contenido_md5":"15ac057634f126f1ce6b8def67d4a94d"},{"identificador":"Artículo Cuarto","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"id":"fd6f30d8-63ee-4fc4-8619-b2165d655cc7","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","orden":5,"contenido_md5":"f4a0be4d1da5824d694afea7fd93bfb9"},{"identificador":"Artículo Quinto","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"id":"0f48ab42-9acd-48b6-a398-aee5486048b6","ley_id":"ffa0dcbe-6f52-45da-bbbb-