65f6410c2c9a","orden":13,"contenido_md5":"82df9862cdc44b8f9188c333dde2cba0"},{"identificador":"Artículo Décimo Tercero","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"id":"a1b63067-2aed-4def-a740-bdee485040eb","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","orden":14,"contenido_md5":"2f39204877bca87525e3ab5212275f9b"},{"identificador":"Transitorio Primero","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"398f3391-e4af-42a9-ae52-d7f5c428c852","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","orden":15,"contenido_md5":"a0fa8adf74493f041e6cb3c39bcd9db6"},{"identificador":"Transitorio Segundo","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"31f1f7b6-6b3e-4dd7-a644-5a5d58a5dd68","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","orden":16,"contenido_md5":"6fe311bc51d993d766d872272fe9d412"},{"identificador":"Transitorio Tercero","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"ef116f11-bed4-467e-bfcf-f21d8ef62417","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","orden":17,"contenido_md5":"b3d6919cb7109b92716283871bc2da34"},{"identificador":"Firmas y promulgación","tipo_articulo":"complementario","titulo_nombre":"Documentos complementarios","capitulo_nombre":null,"seccion_nombre":null,"id":"88c09923-3d2e-5b79-84fc-1057d911d354","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","orden":18,"contenido_md5":"f6a615e4250be48fbaea19f8bcbec93e"}],"after":[{"id":"17aaa2f6-91e8-4082-b567-fbaf7e7e9c24","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Preámbulo","contenido":"DOF: 22/05/2025 DECRETO por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar. Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Presidencia de la República. CLAUDIA SHEINBAUM PARDO, Presidenta de los Estados Unidos Mexicanos, en ejercicio de la facultad que me confiere el","tipo_articulo":"preambulo","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":0},{"id":"0eb1395e-5a9e-4a3a-a754-6367a7bbf8e5","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"artículo 89","contenido":", fracción I, de la Constitución Política de los Estados Unidos Mexicanos, con fundamento en los artículos 31, 32 Bis, \n33, 34 y 41 de la Ley Orgánica de la Administración Pública Federal, 33 de la Ley de Planeación y 39, primer párrafo, fracción III, \ndel Código Fiscal de la Federación, y \n CONSIDERANDO \n Que, en términos del artículo 25, primer párrafo, de la Constitución Política de los Estados Unidos Mexicanos (CPEUM), \ncorresponde al Estado la rectoría del desarrollo nacional para garantizar que este sea integral y sustentable, que fortalezca la \nSoberanía de la Nación y su régimen democrático y que, mediante la competitividad, el fomento del crecimiento económico y el \nempleo y una más justa distribución del ingreso y la riqueza, permita el pleno ejercicio de la libertad y la dignidad de los \nindividuos, grupos y clases sociales, cuya seguridad protege la Constitución; \n Que el artículo 26, apartado A, de la CPEUM establece que el Estado organizará un sistema de planeación democrático del \ndesarrollo nacional que imprima solidez, dinamismo, competitividad, permanencia y equidad al crecimiento de la economía; \n Que dentro de los \"100 compromisos\" (1) adquiridos por la persona titular del Ejecutivo Federal se encuentra el de promover la \ninversión privada y la relocalización de las empresas con innovación, para lograr una mejora en los salarios de los trabajadores, \nprocurando la protección al medio ambiente y el contenido nacional; \n Que el \"Plan México\", presentado por la Presidenta de la República el 13 de enero de 2025, además de promover el \ncrecimiento económico del país para posicionarlo entre las diez principales economías del mundo y reducir la pobreza y la \ndesigualdad, tiene como objetivo crear una estrategia de industrialización en el país, incrementando la participación de empresas \nmexicanas en la cadena de proveeduría de las exportaciones, permitiendo a las micro, pequeñas y medianas empresas, y no solo \na las grandes corporaciones, a tener un papel más activo en la manufactura de bienes intermedios, insumos y componentes \nesenciales, y el fortalecer el progreso científico, tecnológico y la innovación; así como ampliar el acceso a la educación media \nsuperior y superior; \n Que el Plan Nacional de Desarrollo 2025-2030, publicado en el Diario Oficial de la Federación (DOF) el 15 de abril de 2025, \nconsidera al \"Plan México\" como una herramienta de visión a largo plazo que permitirá a la economía nacional dejar de depender \nde proveedurías extranjeras, respecto de productos que desde hace tiempo el país ya produce con alta calidad; \n Que la implementación de una estrategia basada en el establecimiento de los Polos de Desarrollo Económico para el \nBienestar, representa una oportunidad para la reducción de desigualdades económicas; un impulso para el crecimiento \neconómico sostenible; un motor para la transformación social y un generador de empleos y de bienestar social en diversas \nregiones del país, ya que funcionarán como catalizadores que promoverán la inversión en infraestructuras específicas, desarrollos \nindustriales y proyectos comunitarios, asegurando una distribución más equitativa de los recursos y fomentando la inclusión \neconómica. La creación de Polos de Desarrollo Económico para el Bienestar permitirá conectar las necesidades locales con los \n intereses de inversionistas nacionales e internacionales, maximizando el impacto positivo en las comunidades; \n Que, para poder cumplir con el compromiso del Plan México, es necesario fomentar la vinculación del sector privado y el \ngobierno en sus tres niveles: federal, estatal y municipal. Esto considerando las vocaciones productivas de cada región del país, \npor lo que el establecimiento de los Polos de Desarrollo Económico para el Bienestar es una acción indispensable; \n Que una estrategia similar ha sido instrumentada mediante el \"Decreto por el que se fomenta la inversión de los \ncontribuyentes que realicen actividades económicas productivas al interior de los Polos de Desarrollo para el Bienestar del istmo \nde Tehuantepec\" y el \"Decreto por el que se fomenta la inversión en los Polos Industriales del Bienestar Progreso I y Mérida I del \nestado de Yucatán\", publicados en el DOF el 5 de junio de 2023 y el 28 de junio de 2024, respectivamente, en los cuales se \notorgaron estímulos fiscales y facilidades administrativas; \n Que la instrumentación de estímulos fiscales es una herramienta para potenciar la actividad económica local al promover la \ncreación de empleo, el desarrollo sustentable , la economía circular y el retorno de las inversiones; para fomentar la diversificación \ny crecimiento económico equilibrado en las distintas regiones del país, reduciendo la dependencia de sectores tradicionales; en \nvirtud de que su diseño adecuado, no solo permite fortalecer la competitividad de las empresas de nueva creación, sino que \ntambién atraen inversiones públicas y privadas estratégicas; \n Que, en razón de lo anterior, y en congruencia con la estrategia del \"Plan México\", la persona titular del Ejecutivo Federal \nconsidera conveniente conceder estímulos fiscales a los contribuyentes que inicien operaciones y realicen actividades \neconómicas productivas al interior de los Polos de Desarrollo Económico para el Bienestar, lo anterior a fin de incentivar la \neconomía en regiones en las que se establezcan dicho polos a partir de vocaciones regionales productivas, prioritarias y \npotenciales; \n Que, en razón de la importancia de incentivar a contribuyentes para establecerse en regiones con oportunidad de desarrollo \neconómico, se considera conveniente otorgar a los contribuyentes que inicien operaciones y que realicen actividades económicas \nproductivas al interior de los Polos de Desarrollo Económico para el Bienestar, así como a los que cuenten con autorización para \nser considerados como desarrolladores, el estímulo fiscal consistente en la deducción inmediata al 100% de las inversiones en \nbienes nuevos de activo fijo para efectos de la determinación del impuesto sobre la renta, durante los ejercicios fiscales de 2025, \n 8/6/26, 13:23 DOF - Diario Oficial de la Federación \n https://www.dof.gob.mx/nota_detalle.php?codigo=5758077&fecha=22/05/2025&print=true 1/6 \n\n2026, 2027, 2028, 2029 o 2030, a efecto de que cuenten con flujo de recursos, de manera anticipada, y recuperen el capital \ninvertido en maquinaria, equipo, infraestructura, entre otros; \n Que para mejorar la productividad laboral y asegurar que las comunidades locales sean parte integral del crecimiento \neconómico, se considera adecuado promover la inversión en capacitación especializada, por lo que se propone establecer como \nestímulo fiscal una deducción adicional del 25% por los gastos incrementales de capacitación o innovación para efectos del \nimpuesto sobre la renta del ejercicio, misma que podrán aplicar los contribuyentes que realicen actividades económicas al interior \nde los Polos de Desarrollo Económico para el Bienestar, en la declaración anual de los ejercicios fiscales de 2025, 2026, 2027, \n2028, 2029 o 2030, con lo cual se responde a la necesidad de desarrollar la creación de fuentes de trabajo y mano de obra \nespecializada en las regiones seleccionadas, asegurando que las personas cuenten con habilidades que las conecten con las \noportunidades laborales generadas por las nuevas inversiones; \n Que, para el establecimiento de los Polos de Desarrollo Económico para el Bienestar, resulta necesario establecer medidas de \nselección, evaluación y control de los polos que promuevan la transparencia y otorguen certidumbre, por lo que el Ejecutivo \nFederal a mi cargo, considera necesario crear un Comité Intersecretarial de Promoción, el cual estará integrado por un \nrepresentante de la Secretaría de Economía quien presidirá dicho comité, por representantes de las secretarías de Hacienda y \nCrédito Público, de Desarrollo Agrario, Territorial y Urbano, de Energía y de Medio Ambiente y Recursos Naturales; con la \n participación de invitados permanentes de la Comisión Federal de Electricidad, de la Comisión Nacional del Agua y del Consejo \nAsesor de Desarrollo Económico Regional y Relocalización ; \n Que, entre otras funciones, dicho Comité Intersecretarial de Promoción, considerando cada dictamen de viabilidad formulado \npor sus integrantes, emitirá un dictamen colegiado a la Secretaría de Economía para que, en su caso, determine y emita la \nDeclaratoria de los Polos de Desarrollo Económico para el Bienestar, una vez que estos cumplan con los criterios de selección \nque se establezcan en los lineamientos que al efecto emita dicho Comité; \n Que las entidades federativas podrán proponer superficies de terrenos, con el objeto de que puedan ser declarados por la \nSecretaría de Economía como Polos de Desarrollo Económico para el Bienestar. Esto permitirá que las entidades celebren \nconvenios de coordinación con la federación, a través de la Secretaría de Economía y otorguen autorizaciones a las empresas \ninteresadas en fungir como desarrolladores, siempre que cumplan con los requisitos establecidos en las convocatorias publicadas \nde conformidad con los lineamientos que para tal efecto emita el Comité Intersecretarial de Promoción; \n Que para el desarrollo, operación y administración de cada uno de los Polos de Desarrollo Económico para el Bienestar , las \nentidades federativas podrán crear un vehículo de propósito especial en el que participen sujetos públicos y privados, de acuerdo \ncon los lineamientos que para tal efecto emita el comité , y \n Que con el objetivo de impulsar la competitividad y favorecer la operación de los contribuyentes que realicen actividades \neconómicas productivas al interior de los Polos de Desarrollo Económico para el Bienestar y de quienes obtengan autorización \ncomo desarrolladores, y en el ejercicio de la facultad establecida en el artículo 39, primer párrafo, fracción III, del Código Fiscal de \nla Federación, he tenido a bien expedir el siguiente \n DECRETO","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":1},{"id":"40a07017-0bf5-4749-8186-1aedb3b5a1d7","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo Primero.","contenido":"Se otorgan estímulos fiscales a los contribuyentes personas físicas y morales residentes en México y a los \nresidentes en el extranjero con establecimiento permanente en el país que tributen en los términos del Título II; del Título IV, \nCapítulo II, Sección I, o del Título VII, Capítulo XII, de la Ley del Impuesto sobre la Renta, que inicien operaciones con \nposterioridad a la entrada en vigor del presente decreto y realicen actividades económicas productivas al interior de los Polos de \nDesarrollo Económico para el Bienestar . \n La Secretaría de Economía emitirá y publicará en el Diario Oficial de la Federación la declaratoria de los Polos de Desarrollo \nEconómico para el Bienestar una vez que se determine la viabilidad del mismo , considerando el dictamen colegiado que emita el \n Comité Intersecretarial de Promoción a que se refiere el artículo Décimo de este decreto, en los términos y condiciones que se \nestablezcan en los lineamientos que para tal efecto emita dicho comité. Cuando por la naturaleza económica, industrial o \ngeográfica del Polo de Desarrollo Económico para el Bienestar lo requiera, la Secretaría de Economía podrá emitir la declaratoria \nde forma directa sin la intervención del comité. \n Las personas morales que tributen en los términos del Título II, o del Título VII, Capítulo XII de la Ley del Impuesto sobre la \nRenta, que hayan obtenido autorización que los acredite como desarrolladores de un Polo de Desarrollo Económico para el \nBienestar, podrán aplicar los estímulos fiscales a que se refieren los artículos Tercero y Cuarto del presente decreto.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":2},{"id":"804492c8-dafb-4f70-b11d-452c93a0c355","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo Segundo.","contenido":"Los contribuyentes interesados en obtener los estímulos fiscales previstos en el presente decreto, deben \ncumplir con los siguientes requisitos: \n A. Los contribuyentes a que se refiere el primer párrafo del artículo Primero: \n I. Estar al corriente en el cumplimiento de sus obligaciones fiscales para lo cual deben contar con la opinión positiva del \ncumplimiento de obligaciones fiscales a que se refiere el artículo 32-D del Código Fiscal de la Federación ; \n II. Tener su domicilio fiscal en el Polo de Desarrollo Económico para el Bienestar donde desarrollen sus actividades \neconómicas productivas, y \n III. Contar con el Convenio de colaboración celebrado con la Secretaría de Educación Pública en materia de educación dual; \nel Proyecto de inversión para el desarrollo de invenciones susceptibles de protección mediante patentes o el registro de \nmodelos de utilidad, o bien, el Proyecto de inversión para la obtención de certificación inicial, según sea el caso; este \nrequisito únicamente es aplicable para los efectos del estímulo fiscal previsto en el artículo Cuarto del presente decreto. \n B. Los desarrolladores deben cumplir con las fracciones I y III del apartado A de este artículo, y presentar la autorización \nque haya sido otorgada por la entidad federativa en los términos y condiciones que se establezcan en los lineamientos que para \n 8/6/26, 13:23 DOF - Diario Oficial de la Federación \n https://www.dof.gob.mx/nota_detalle.php?codigo=5758077&fecha=22/05/2025&print=true 2/6 \n\ntal efecto emita el Comité Intersecretarial de Promoción. \n Cuando los contribuyentes o desarrolladores dejen de cumplir con alguno de los requisitos previstos en este decreto, dejarán \nde aplicar los estímulos fiscales a partir del momento en que se dé el incumplimiento; debiendo cubrir el impuesto, la actualización \ny los recargos correspondientes, conforme a las disposiciones legales aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":3},{"id":"521f56bf-ff11-42b8-b36b-40d2d34e5e7a","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo Tercero.","contenido":"Los contribuyentes y los desarrolladores a que se refiere el artículo Primero de este Decreto, durante los \nejercicios fiscales de 2025, 2026, 2027, 2028, 2029 o 2030, podrán efectuar la deducción inmediata del 100% del monto original \nde la inversión de bienes nuevos de activo fijo que utilicen para realizar sus actividades económicas productivas o aquellos bienes \nnuevos de activo fijo relacionados totalmente con la actividad de los desarrolladores, según sea el caso, que se realicen \n exclusivamente al interior de los referidos polos, en lugar de aplicar los por cientos máximos autorizados a que se refieren los \nartículos 34, 35, 104 o 209, apartados B y C, de la Ley del Impuesto sobre la Renta, según corresponda. Se consideran bienes \n nuevos los que se utilizan por primera vez en México. \n Los contribuyentes a que se refiere el párrafo anterior podrán aplicar la deducción inmediata de bienes nuevos de activo fijo a \nque se refiere dicho párrafo respecto de aquellos bienes que se hayan adquirido a partir de que la entidad federativa celebre el \nconvenio de coordinación a que se refiere el artículo Décimo de este decreto y hasta el 30 de septiembre de 2030. Los \ndesarrolladores aplicarán el estímulo a que se refiere este artículo respecto de aquellos bienes que se hayan adquirido a partir de \nque hayan sido autorizados por la entidad federativa en términos del artículo Décimo Primero de este decreto y hasta el 30 de \nseptiembre de 2030. \n Lo dispuesto en este artículo solo será aplicable respecto de aquellas inversiones que los contribuyentes mantengan en uso \ndurante un periodo mínimo de dos años inmediatos siguientes al ejercicio en el que se efectúe su deducción inmediata, salvo en \nlos casos a que hace referencia el artículo 37 de la Ley del Impuesto sobre la Renta. \n Para los efectos de este artículo, los contribuyentes y los desarrolladores pueden efectuar la deducción inmediata de \ninversiones en el ejercicio fiscal en el que inicien su utilización o, en su defecto, en el siguiente. \n Cuando se transmita la propiedad de los bienes por los que se haya aplicado la deducción inmediata, a través de cualquier \nfigura jurídica, se deberá acumular el monto que resulte mayor entre el total de los ingresos obtenidos por la transmisión de \npropiedad y el valor en que dichos bienes se hubieran enajenado entre partes independientes en operaciones comparables. \n La opción a que se refiere este artículo no puede ejercerse cuando se trate de mobiliario y equipo de oficina, automóviles \npropulsados con motores de combustión interna, equipo de blindaje de automóviles o cualquier bien de activo fijo no identificable \nindividualmente, ni tratándose de aviones distintos de los dedicados a la aerofumigación agrícola. \n Para los efectos del artículo 14, fracción I, primer párrafo de la Ley del Impuesto sobre la Renta, los contribuyentes y \ndesarrolladores adicionarán a la utilidad fiscal o reducirán de la pérdida fiscal del ejercicio por el que calculen el coeficiente de \nutilidad, según sea el caso, con el importe de la deducción inmediata a que se refiere este artículo, realizada en el citado ejercicio. \n La utilidad fiscal que se determine en los términos del artículo 14, fracción II, de la Ley del Impuesto sobre la Renta podrá \ndisminuirse con el monto de la deducción inmediata efectuada en el mismo ejercicio. El citado monto de la deducción inmediata \nse debe disminuir por partes iguales en los pagos provisionales correspondientes al ejercicio fiscal de que se trate, a partir del \nmes en que se inicie su utilización o, en su defecto, en el ejercicio fiscal siguiente, según la opción elegida. Esta disminución se \ndebe realizar en los pagos provisionales del ejercicio de manera acumulativa, sin que en ningún caso sea superior a la utilidad \n fiscal correspondiente al periodo en que se aplica, ya sea individual o en conjunto con otras disminuciones fiscales. Para los \nefectos de este párrafo, no se podrá recalcular el coeficiente de utilidad determinado en los términos del artículo 14, fracción I, de \nla Ley del Impuesto sobre la Renta. \n Los contribuyentes y los desarrolladores deben llevar un registro específico de las inversiones por las que se optó por aplicar \nla deducción inmediata en los términos de este artículo, que contenga la documentación comprobatoria que las respalde, \ndescripción el tipo de bien de que se trate, la relación con sus actividades que realicen al interior de los Polos de Desarrollo \nEconómico para el Bienestar, el proceso o actividad en específico en el cual se utilizó el bien, el ejercicio en el que se aplicó la \ndeducción y, en su caso, la fecha en la que el bien se enajene, se pierda por caso fortuito o fuerza mayor o deje de ser útil, de \nconformidad con las reglas de carácter general que para tal efecto emita el Servicio de Administración Tributaria.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":4},{"id":"fd6f30d8-63ee-4fc4-8619-b2165d655cc7","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo Cuarto.","contenido":"Los contribuyentes y los desarrolladores a que se refiere el artículo Primero de este decreto, podrán aplicar \nen la declaración anual del impuesto sobre la renta de los ejercicios fiscales de 2025, 2026, 2027, 2028, 2029 y 2030 un estímulo \nfiscal consistente en una deducción adicional equivalente al 25% del incremento en el gasto erogado por concepto de \ncapacitación que reciba cada uno de sus trabajadores en el ejercicio fiscal de que se trate o por los gastos erogados por concepto \nde innovación. Para estos efectos, el incremento se determinará conforme a lo siguiente: \n I. Para el ejercicio fiscal en que los contribuyentes inicien operaciones o los desarrolladores inicien la prestación de sus \nservicios, que opten por aplicar el estímulo fiscal a que se refiere este artículo, el incremento será el importe \ncorrespondiente de los gastos erogados por concepto de capacitación o innovación en dicho ejercicio fiscal. \n II. Para el segundo ejercicio fiscal, el incremento será la diferencia positiva entre el gasto erogado por concepto de \ncapacitación o innovación en dicho ejercicio fiscal y el gasto erogado por el contribuyente o el desarrollador en los \nmismos conceptos en el ejercicio fiscal inmediato anterior. \n III. Para el tercer ejercicio fiscal, el incremento será la diferencia positiva entre el gasto erogado por concepto de \ncapacitación o innovación en el ejercicio fiscal correspondiente y el gasto promedio erogado por el contribuyente o el \ndesarrollador en los mismos conceptos en los dos ejercicios fiscales inmediatos anteriores. \n IV. A partir del cuarto ejercicio fiscal y posteriores, el incremento será la diferencia positiva entre el gasto erogado por \nconcepto de capacitación o innovación en el ejercicio fiscal correspondiente y el gasto promedio erogado por el \n 8/6/26, 13:23 DOF - Diario Oficial de la Federación \n https://www.dof.gob.mx/nota_detalle.php?codigo=5758077&fecha=22/05/2025&print=true 3/6 \n\ncontribuyente o el desarrollador en los mismos conceptos en los tres ejercicios fiscales inmediatos anteriores, \npromediando incluso si en dichos ejercicios no se erogó gasto alguno por esos conceptos. \n La capacitación a que se refiere este artículo, será aquélla que proporcione conocimientos técnicos o científicos vinculados \ncon la actividad del contribuyente. \n Los gastos por concepto de innovación a que se refiere este artículo, serán aquellos vinculados con los proyectos de inversión \npara el desarrollo de la invención, que permitan la obtención de patentes o registros de modelos de utilidad, y aquellos proyectos \nde inversión que se desarrollen para la obtención de certificaciones iniciales que requieran los contribuyentes para su integración \na las cadenas de proveedurías local/regional. \n La deducción adicional por concepto de gastos de capacitación, sólo será procedente respecto de la capacitación \nproporcionada por los contribuyentes o los desarrolladores a sus trabajadores activos registrados ante el Instituto Mexicano del \nSeguro Social, y que dichos contribuyentes o desarrolladores cuenten con un programa de Educación dual autorizado por la \nSecretaría de Educación Pública. \n Los contribuyentes o desarrolladores que no apliquen la deducción adicional establecida en este artículo en el ejercicio en el \nque realicen el gasto, perderán el derecho de hacerlo en los ejercicios posteriores. \n La deducción adicional a que se refiere este artículo en el ejercicio de que se trate, se debe restar de la diferencia entre los \ningresos acumulables obtenidos en dicho ejercicio y las deducciones autorizadas conforme a la Ley del Impuesto sobre la Renta y \nhasta por el monto de dicha diferencia. En el caso de que las deducciones autorizadas conforme a la Ley del Impuesto sobre la \nRenta sean mayores que los ingresos acumulables obtenidos en el ejercicio, no se disminuirá monto alguno por concepto de la \ndeducción adicional a que se refiere el presente artículo. \n Los contribuyentes y los desarrolladores, según sea el caso, deben realizar el registro específico en su contabilidad de los \ngastos de capacitación, y de proyectos de inversión para el desarrollo de la invención o de certificación inicial, según sea el caso, \nen los términos de este artículo y contar con la documentación comprobatoria que los respalde, así como describir \nespecíficamente en qué consistió dicha capacitación o los proyectos de inversión para el desarrollo de la invención o de \ncertificación inicial, y la relación que guarda con las actividades económicas que realicen al interior de los Polos de Desarrollo \nEconómico para el Bienestar, de conformidad con las reglas de carácter general que para tal efecto emita el Servicio de \nAdministración Tributaria.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":5},{"id":"0f48ab42-9acd-48b6-a398-aee5486048b6","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo Quinto.","contenido":"Para los efectos de los artículos Tercero y Cuarto de este decreto, los contribuyentes y los desarrolladores \n deben determinar el impuesto sobre la renta causado en el ejercicio y sus pagos provisionales de acuerdo con los artículos 9, 14, \n106, 109, 211 o 212 de la Ley del Impuesto sobre la Renta, según corresponda, considerando únicamente los ingresos atribuibles \na las actividades económicas productivas o aquellos ingresos relacionados con la actividad de los desarrolladores, según sea el \ncaso, que se realicen al interior de los Polos de Desarrollo Económico para el Bienestar a que se refiere este decreto, así como \nlas deducciones que sean estrictamente indispensables para la obtención de dichos ingresos y además cumplan los otros \nrequisitos establecidos en los artículos 27, 105 o 210 de la Ley del Impuesto sobre la Renta, según corresponda. \n Cuando el monto de las deducciones mencionadas en el párrafo anterior, sea mayor que los citados ingresos, la diferencia \nserá una pérdida fiscal y solo podrá disminuirse de la utilidad fiscal derivada de las actividades económicas productivas o de la \nactividad de los desarrolladores, según sea el caso, realizadas al interior de los Polos de Desarrollo Económico para el Bienestar \na que se refiere este decreto, para lo cual será aplicable lo dispuesto en los artículos 57, 109 o 212 de la Ley del Impuesto sobre \nla Renta, según corresponda. \n Cuando los contribuyentes y desarrolladores obtengan ingresos distintos de los señalados en este artículo, deben determinar \npor separado el impuesto sobre la renta por dichos ingresos conforme a las disposiciones de la Ley del Impuesto sobre la Renta \nque establece dicho gravamen, sin aplicar los estímulos fiscales a que se refiere este decreto. \n Para los efectos de lo dispuesto en este artículo, los contribuyentes y desarrolladores deben presentar las declaraciones a las \nque se encuentren obligados a través de los sistemas que disponga el Servicio de Administración Tributaria y realizar los pagos \nque correspondan, conforme a las disposiciones fiscales aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":6},{"id":"5d0545e9-d0a9-4c69-baf7-6f3c02aae7d4","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo Sexto.","contenido":"Los contribuyentes y desarrolladores que apliquen los estímulos fiscales establecidos en este decreto, no \npodrán aplicar conjuntamente: \n I. Lo dispuesto en los artículos 181 y 182 de la Ley del Impuesto sobre la Renta; \n II. El régimen opcional para grupos de sociedades, establecido en el Título II, Capítulo VI, de la Ley del Impuesto sobre la \nRenta; \n III. Lo dispuesto en los artículos 187 y 188 de la Ley del Impuesto sobre la Renta, respecto a los fideicomisos dedicados a la \nadquisición o construcción de inmuebles; \n IV. Los estímulos fiscales a que se refieren los artículos 189, 190, 202 y 203 de la Ley del Impuesto sobre la Renta, y \n V. Los estímulos fiscales otorgados a través del \"Decreto por el que se otorgan estímulos fiscales para apoyar la estrategia \nnacional denominada \"Plan México\", para fomentar nuevas inversiones, que incentiven programas de capacitación dual e \nimpulsen la innovación\", publicado en el Diario Oficial de la Federación el 21 de enero de 2025; así como sus posteriores \nmodificaciones.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":7},{"id":"20bc5555-08d3-4d5a-8bf9-e03e247a416d","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo   Séptimo.","contenido":"No procederá la aplicación de los estímulos fiscales establecidos en este decreto cuando los \ncontribuyentes o desarrolladores se encuentren en cualquiera de los siguientes supuestos: \n I. Se ubiquen en alguno de los supuestos establecidos en el artículo 69, penúltimo párrafo, del Código Fiscal de la \nFederación y cuyo nombre, denominación o razón social y clave en el Registro Federal de Contribuyentes se encuentren \n 8/6/26, 13:23 DOF - Diario Oficial de la Federación \n https://www.dof.gob.mx/nota_detalle.php?codigo=5758077&fecha=22/05/2025&print=true 4/6 \n\ncontenidos en la publicación de la página de Internet del Servicio de Administración Tributaria a que se refiere el último \npárrafo del citado artículo. \n II. No desvirtúen la presunción establecida en el artículo 69-B, primer párrafo, del Código Fiscal de la Federación y, por \ntanto, se encuentran definitivamente en dicha situación en términos del cuarto párrafo de dicho artículo. Asimismo, \ntampoco será aplicable a los contribuyentes que tengan un socio o accionista que se encuentre en el supuesto de \npresunción a que se refiere esta fracción. Tampoco serán aplicables los estímulos fiscales previstos en el presente \ndecreto, a aquellos contribuyentes que hubieran realizado operaciones con contribuyentes a los que se refiere esta \nfracción y no hubieran acreditado ante las autoridades fiscales que efectivamente adquirieron los bienes o recibieron los \nservicios que amparan los comprobantes fiscales digitales correspondientes. \n III. Se les haya aplicado la presunción establecida en el artículo 69-B Bis del Código Fiscal de la Federación, una vez que se \nhaya publicado en el Diario Oficial de la Federación y en la página de Internet del Servicio de Administración Tributaria el \nlistado a que se refiere dicho artículo. \n IV. Tengan créditos fiscales firmes o, que al ser exigibles, no estén garantizados o bien, que la garantía resulte insuficiente. \n V. No cumplan con cualquiera de los requisitos establecidos en el presente decreto, entre ellos los registros específicos de \nlas inversiones y de capacitación e innovación a que se refiere este decreto. \n VI. Se encuentren en ejercicio de liquidación. \n VII. Se encuentren en el procedimiento de restricción temporal del uso de sellos digitales para la expedición de \ncomprobantes fiscales digitales por Internet, de conformidad con el artículo 17-H Bis del Código Fiscal de la Federación. \n VIII. Tengan cancelados los certificados emitidos por el Servicio de Administración Tributaria para la expedición de \ncomprobantes fiscales digitales por Internet, de conformidad con el artículo 17-H del Código Fiscal de la Federación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":8},{"id":"82904284-c422-40f8-ad15-698ea8487604","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo Octavo.","contenido":"Los estímulos fiscales previstos en este decreto no se consideran como ingreso acumulable para los efectos \ndel impuesto sobre la renta.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":9},{"id":"245f82db-b475-4f25-8b37-95c56ace00a6","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo Noveno.","contenido":"Para los efectos del presente decreto se debe aplicar, en forma supletoria, la Ley del Impuesto sobre la \nRenta y el Código Fiscal de la Federación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":10},{"id":"9daf1b33-e3bf-4ca7-98ed-093b2cdf7b8e","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo Décimo.","contenido":"Para el establecimiento de los Polos de Desarrollo Económico para el Bienestar se crea un Comité \nIntersecretarial de Promoción integrado por un representante de la Secretaría de Economía quien presidirá dicho comité, y por un \nrepresentante de las secretarías de Hacienda y Crédito Público, de Desarrollo Agrario, Territorial y Urbano, de Energía y de Medio \nAmbiente y Recursos Naturales, quienes tendrán nivel mínimo de subsecretarios. Serán invitados permanentes representantes de \nla Comisión Federal de Electricidad, de la Comisión Nacional del Agua y del Consejo Asesor de Desarrollo Económico Regional y \n Relocalización. \n El comité tiene como objeto emitir un dictamen colegiado para la determinación de los Polos de Desarrollo Económico para el \nBienestar , considerando los dictámenes de viabilidad formulados por sus integrantes, en el ámbito de sus competencias; así como \nel análisis de las propuestas de las superficies de terrenos que tengan como fin ser declarados por la Secretaría de Economía \ncomo Polos de Desarrollo Económico para el Bienestar . Para estos efectos, el comité emitirá los lineamientos en los que \nestablecerá, entre otros, su integración, atribuciones, quorum, desarrollo de sesiones, criterios de selección que deben cumplir las \n propuestas de superficies de terrenos, así como las convocatorias de los concursos que lleven a cabo las entidades federativas. \n Las entidades federativas interesadas en proponer una superficie de terreno para que sea considerada como Polo de \nDesarrollo Económico para el Bienestar , una vez emitida la declaratoria correspondiente, conforme lo establezcan los \nlineamientos, deben celebrar un convenio de coordinación con la Secretaría de Economía, de conformidad con lo dispuesto en la \nLey de Planeación, y cumplir con los requisitos, términos y condiciones que se establezcan en los lineamientos que emita para tal \nefecto el Comité Intersecretarial de Promoción.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":11},{"id":"ef888344-5b14-4457-8235-fda4e5c655b5","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo Décimo Primero.","contenido":"Para los efectos del artículo Primero, tercer párrafo, del presente decreto se entenderá por \ndesarrolladores a las personas morales que , con base en la autorización otorgada por la entidad federativa, desarrollará el Polo \nde Desarrollo Económico para el Bienestar, quienes podrán tener a su cargo la construcción, desarrollo y administración del \nmismo, en los términos y condiciones que se establezcan en los lineamientos que emita para tal efecto el Comité Intersecretarial \nde Promoción. \n Para otorgar la autorización a que se refiere el párrafo anterior, las entidades federativas podrán optar por el procedimiento de \nasignación directa, o bien, emitirán convocatorias públicas en el Diario Oficial de la Federación y realizarán concursos públicos \nconforme a lo dispuesto en los lineamientos que emita para tal efecto el referido Comité .","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":12},{"id":"0987c704-bf1e-47bc-8848-1ac0728aca69","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo Décimo Segundo.","contenido":"Para el desarrollo, operación y administración de los Polos de Desarrollo Económico para el \nBienestar a que se refiere el presente decreto, las entidades federativas podrán crear vehículos de propósito especial en los \ntérminos y condiciones que se establezcan en los lineamientos que emita para tal efecto el Comité Intersecretarial de Promoción, \ny en las disposiciones jurídicas aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":13},{"id":"a1b63067-2aed-4def-a740-bdee485040eb","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Artículo Décimo Tercero.","contenido":"El Servicio de Administración Tributaria debe emitir las reglas de carácter general necesarias para \nla debida y correcta aplicación de los estímulos fiscales, así como de las demás disposiciones del presente decreto.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":14},{"id":"398f3391-e4af-42a9-ae52-d7f5c428c852","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Transitorio PRIMERO.","contenido":"El presente decreto entra en vigor el día de su publicación en el Diario Oficial de la Federación.","tipo_articulo":"transitorio","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":15},{"id":"31f1f7b6-6b3e-4dd7-a644-5a5d58a5dd68","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Transitorio SEGUNDO.","contenido":"Una vez publicado el presente decreto, el Comité Intersecretarial de Promoción deberá emitir y publicar en el \nDiario Oficial de la Federación los lineamientos para los Polos de Desarrollo Económico para el Bienestar en un plazo no mayor a \n30 días naturales. \n 8/6/26, 13:23 DOF - Diario Oficial de la Federación \n https://www.dof.gob.mx/nota_detalle.php?codigo=5758077&fecha=22/05/2025&print=true 5/6","tipo_articulo":"transitorio","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":16},{"id":"ef116f11-bed4-467e-bfcf-f21d8ef62417","ley_id":"ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a","identificador":"Transitorio TERCERO.","contenido":"Las erogaciones que se generen con motivo de la entrada en vigor del presente decreto, deben cubrirse con cargo \nal presupuesto aprobado para el presente ejercicio fiscal y subsecuentes de las dependencias y entidades competentes, toda vez \nque no se autorizarán ampliaciones al presupuesto regularizable de dichas Dependencias y Entidades. \n Dado en la Residencia del Poder Ejecutivo Federal, en Ciudad de México a 22 de mayo de 2025.- Presidenta de los Estados \nUnidos Mexicanos , Claudia Sheinbaum Pardo .- Rúbrica.- Secretario de Hacienda y Crédito Público , Édgar Abraham Amador \nZamora .- Rúbrica.- Secretaria de Medio Ambiente y Recursos Naturales , Alicia Isabel Adriana Bárcena Ibarra .- Rúbrica.- \n Secretaria de Energía , Luz Elena González Escobar .- Rúbrica.- Secretario de Economía , Marcelo Luis Ebrard Casaubon .- \nRúbrica.- Secretaria de Desarrollo Agrario , Territorial y Urbano , Edna Elena Vega Rangel .- Rúbrica. \n 1 https://www.gob.mx/presidencia/es/articulos/version-estenografica-mensaje-de-la-presidenta-de-los-estados- unidos- mexicanos-claudia-sheinbaum-pardo?idiom=es \n 8/6/26, 13:23 DOF - Diario Oficial de la Federación \n https://www.dof.gob.mx/nota_detalle.php?codigo=5758077&fecha=22/05/2025&print=true 6/6","tipo_articulo":"transitorio","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":17}],"remove":["88c09923-3d2e-5b79-84fc-1057d911d354"],"themes_before":[],"themes_after":[],"date_before":"2025-05-22","date_after":"2025-05-22"}$payload$::jsonb; lid uuid; n integer;
BEGIN
 lid := (p->>'ley_id')::uuid;
 LOCK TABLE public.articulos, public.temas, public.user_favorites, public.user_notes IN SHARE ROW EXCLUSIVE MODE;
 PERFORM 1 FROM public.leyes WHERE id=lid FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM public.leyes WHERE id=lid AND fecha_publicacion=(p->>'date_before')::date) THEN RAISE EXCEPTION 'Cambió la fecha o el instrumento'; END IF;
 SELECT count(*) INTO n FROM public.articulos WHERE ley_id=lid;
 IF n<>jsonb_array_length(p->'before') THEN RAISE EXCEPTION 'Cambió el conteo antes de aplicar'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'before') b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR md5(a.contenido) IS DISTINCT FROM b->>'contenido_md5' OR (to_jsonb(a)-'contenido'-'fts'-'created_at') IS DISTINCT FROM (b-'contenido_md5')) THEN RAISE EXCEPTION 'El respaldo ya no coincide con los artículos'; END IF;
 IF (SELECT count(*) FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'themes_before') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'themes_before') b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE t.ley_id=lid AND (to_jsonb(t)-'created_at'-'id'-'ley_id')=b)) THEN RAISE EXCEPTION 'Cambió el índice de temas'; END IF;
 IF EXISTS(SELECT 1 FROM public.user_favorites f WHERE f.articulo_id IN(SELECT jsonb_array_elements_text(p->'remove'))) OR EXISTS(SELECT 1 FROM public.user_notes f WHERE f.articulo_id IN(SELECT jsonb_array_elements_text(p->'remove'))) THEN RAISE EXCEPTION 'Hay referencias nuevas a fragmentos que se unirán: revisar traslado'; END IF;
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden)
 SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'after')
 ON CONFLICT(id) DO UPDATE SET identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre,orden=excluded.orden;
 DELETE FROM public.articulos WHERE ley_id=lid AND id IN(SELECT jsonb_array_elements_text(p->'remove')::uuid);
 DELETE FROM public.temas WHERE ley_id=lid;
 insert into public.temas(id,ley_id,nivel,nombre,orden) overriding system value select (t->>'id')::bigint,lid,t->>'nivel',t->>'nombre',(t->>'orden')::int from jsonb_array_elements(p->'themes_after') t;
 UPDATE public.leyes SET fecha_publicacion=(p->>'date_after')::date WHERE id=lid;
